/*!
 * modern-energy-keep-awake-card
 *
 * Keeps Fire OS devices (Echo Show, Fire tablets) from dropping into the
 * ambient/photo-frame screen while a Home Assistant dashboard is open.
 *
 * Why a card and not an iframe:
 * Home Assistant renders its iframe card with allow="fullscreen" only, so the
 * autoplay permission is never delegated into the frame. An iframe-based
 * keeper therefore cannot start on its own — it needs a tap *inside* the
 * frame, which on a 2px-high card is close to impossible to hit. A custom
 * card runs in the dashboard document itself, so any tap anywhere on the
 * dashboard unlocks playback.
 *
 * How it works — three mechanisms, strongest first:
 *   1. A looping muted <video>. On Chromium/Android (which Silk is built on)
 *      *video* playback takes a real screen wake lock; audio does not. This is
 *      the mechanism that actually keeps the display lit. The element must be
 *      genuinely rendered — display:none, visibility:hidden, zero size or
 *      being scrolled out of view all disable the lock — so it is parked as a
 *      few visible pixels in a corner.
 *   2. A looping silent <audio>. This holds a media session, which is what
 *      discourages Fire OS from swapping the browser out for Home Content.
 *   3. navigator.wakeLock, when the page is served over HTTPS.
 *
 * Both media elements live on document.body rather than inside the card, so
 * they survive view switches and keep running on views without this card.
 */
(function () {
  "use strict";

  var VERSION = "1.4.0";

  // 20 s of true silence (8 kbit/s mono MP3) and 5 s of black 64x64 H.264
  // baseline video, both inlined: nothing is ever fetched over the network,
  // so no external service can break this and no request can fail.
  var SILENT = "data:audio/mpeg;base64,";
  var MOVIE = "data:video/mp4;base64,";

  // Size and opacity of the parked video. Overridable with
  // ?keepawake=<px>,<opacity> on the dashboard URL, since an Echo Show offers
  // no developer tools to experiment with.
  var KA_SIZE = 18, KA_OPACITY = 0.04;
  try {
    var kp = /[?&]keepawake=([\d.]+)(?:,([\d.]+))?/.exec(location.search);
    if (kp) {
      KA_SIZE = Math.max(1, Math.min(400, parseFloat(kp[1]) || KA_SIZE));
      if (kp[2] != null) KA_OPACITY = Math.max(0, Math.min(1, parseFloat(kp[2])));
    }
  } catch (e) { /* ignore */ }

  // Fire OS models: AEO** = Echo Show (the 15 reports AEOHY), AFT* = Fire TV,
  // KF* = Fire tablets. Silk/ also matches when desktop mode strips the model.
  var IS_FIRE_OS =
    /\bSilk\/|\bKF[A-Z]{2,}|AmazonWebAppPlatform|\bAEO[A-Z]{2}|\bAFT[A-Z0-9]{1,}/i
      .test(navigator.userAgent || "");
  // ?keepawake=force runs the engine on any device, for testing.
  var FORCE = /[?&]keepawake=force/.test(location.search);

  var engine = window.__modernEnergyCardKeepAwake;

  if (!engine) {
    engine = window.__modernEnergyCardKeepAwake = {
      version: VERSION,
      audio: null,
      video: null,
      host: null,
      lock: null,
      armed: false,          // audio has been audible at least once
      gestured: false,       // a real user interaction has happened
      videoOk: false,        // video is decoding frames
      started: false,
      startedAt: 0,
      gestures: 0,
      recoveries: 0,
      lastFrame: 0,
      listeners: [],
      state: "wait",
      reason: "Startet…",
      note: "",
    };

    engine.notify = function (state, reason) {
      if (engine.state === state && engine.reason === reason) return;
      engine.state = state;
      engine.reason = reason;
      engine.listeners.forEach(function (fn) {
        try { fn(state, reason); } catch (e) { /* ignore */ }
      });
    };

    var playEl = function (el) {
      if (!el) return;
      var p = el.play();
      if (p && p.catch) p.catch(function (e) {
        engine.note = (e && e.name) || "play blocked";
      });
    };

    engine.play = function () { playEl(engine.video); playEl(engine.audio); };

    // Fire OS only treats *audible* playback as a real media session, so the
    // muted start used to satisfy autoplay rules is lifted once a gesture
    // allows it. Unmuting before that just gets the element blocked and left
    // paused, which is worse than staying quietly muted. The video stays muted
    // either way — muted video autoplays everywhere and still takes the lock.
    engine.unmute = function () {
      var a = engine.audio;
      if (!a || !a.muted || !engine.gestured) return;
      a.muted = false;
      playEl(a);
    };

    engine.requestLock = function () {
      if (engine.lock || !navigator.wakeLock || !window.isSecureContext) return;
      navigator.wakeLock.request("screen").then(function (l) {
        engine.lock = l;
        l.addEventListener("release", function () { engine.lock = null; });
      }).catch(function () { /* denied; the media path still works */ });
    };

    engine.start = function () {
      if (engine.started) return;
      engine.started = true;
      engine.startedAt = Date.now();

      // A rendered, on-screen host. Chromium hands out its video wake lock only
      // while the element is genuinely being painted and intersects the
      // viewport, so this must not be display:none, visibility:hidden, zero
      // sized or scrolled away. A small dark square pinned to the bottom-right
      // corner satisfies that while staying invisible against a dark
      // dashboard. Community reports have this working down to 1x1 px, but a
      // slightly larger box is safer against Chromium's minimum-visible-area
      // heuristics.
      var host = document.createElement("div");
      host.id = "modern-energy-keep-awake-host";
      host.style.cssText = [
        "position:fixed", "right:0", "bottom:0",
        "width:" + KA_SIZE + "px", "height:" + KA_SIZE + "px",
        "opacity:" + KA_OPACITY, "pointer-events:none",
        "z-index:0", "overflow:hidden", "background:#000",
      ].join(";");
      engine.host = host;

      var v = document.createElement("video");
      v.src = MOVIE;
      v.loop = true;
      v.muted = true;               // muted video autoplays without a gesture
      v.defaultMuted = true;
      v.autoplay = true;
      v.controls = false;
      v.disablePictureInPicture = true;
      v.setAttribute("playsinline", "");
      v.setAttribute("webkit-playsinline", "");
      v.setAttribute("muted", "");
      v.setAttribute("autoplay", "");
      v.style.cssText = "width:" + KA_SIZE + "px;height:" + KA_SIZE +
                        "px;display:block;object-fit:cover";
      engine.video = v;
      host.appendChild(v);

      var a = document.createElement("audio");
      a.src = SILENT;
      a.loop = true;
      a.preload = "auto";
      a.controls = false;
      a.muted = true;
      a.setAttribute("playsinline", "");
      engine.audio = a;
      host.appendChild(a);

      document.body.appendChild(host);

      // A pause means something took focus (Alexa timer, announcement, a call).
      // Answer immediately and keep re-checking; the original iframe version
      // stopped watching after the first successful start, so one interruption
      // killed it permanently.
      [v, a].forEach(function (el) {
        el.addEventListener("pause", function () {
          engine.recoveries++;
          setTimeout(function () { playEl(el); }, 300);
        });
        el.addEventListener("ended", function () { playEl(el); });
        el.addEventListener("stalled", function () { playEl(el); });
        el.addEventListener("error", function () {
          el.src = el === v ? MOVIE : SILENT;
          el.load();
          playEl(el);
        });
      });

      // Counting decoded frames is the only trustworthy signal that the video
      // is really running — currentTime alone can advance on a stalled element.
      var seen = 0;
      var frameTick = function () {
        seen++;
        engine.lastFrame = Date.now();
        if (seen > 2) engine.videoOk = true;
        if (v.requestVideoFrameCallback) v.requestVideoFrameCallback(frameTick);
      };
      if (v.requestVideoFrameCallback) {
        v.requestVideoFrameCallback(frameTick);
      } else {
        v.addEventListener("timeupdate", function () {
          engine.lastFrame = Date.now();
          engine.videoOk = !v.paused;
        });
      }

      var gesture = function () {
        engine.gestures++;
        engine.gestured = true;
        engine.unmute();
        engine.play();
        engine.requestLock();
      };
      ["pointerdown", "touchstart", "click", "keydown"].forEach(function (ev) {
        document.addEventListener(ev, gesture, { capture: true, passive: true });
      });

      var wake = function () { engine.play(); engine.requestLock(); };
      document.addEventListener("visibilitychange", function () {
        if (!document.hidden) wake();
      });
      window.addEventListener("focus", wake);
      window.addEventListener("pageshow", wake);

      engine.tick = function () {
        var vOn = v && !v.paused && !v.ended;
        var aOn = a && !a.paused && !a.ended;
        var fresh = Date.now() - engine.lastFrame < 4000;

        if (vOn && fresh) {
          engine.videoOk = true;
          engine.armed = engine.armed || !a.muted;
          engine.notify("on", a.muted ? "Bildschirm bleibt an (Video)"
                                      : "Bildschirm bleibt an");
        } else if (vOn || aOn) {
          engine.play();
          engine.unmute();
          engine.notify("wait", "Startet…");
        } else {
          engine.play();
          engine.notify(engine.started && (engine.armed || engine.videoOk) ? "off" : "wait",
            engine.armed || engine.videoOk
              ? "Unterbrochen – tippe irgendwo"
              : "Tippe irgendwo zum Aktivieren");
        }
        if (!engine.lock) engine.requestLock();
      };

      engine.play();
      engine.requestLock();
      engine.tick();
      setInterval(engine.tick, 2000);
    };

    engine.report = function () {
      var v = engine.video, a = engine.audio;
      return {
        version: VERSION,
        state: engine.state,
        reason: engine.reason,
        video_spielt: !!(v && !v.paused && !v.ended),
        video_frames_frisch: Date.now() - engine.lastFrame < 4000,
        video_zeit: v ? +v.currentTime.toFixed(1) : null,
        video_fehler: v && v.error ? v.error.code : null,
        audio_spielt: !!(a && !a.paused && !a.ended),
        audio_stumm: a ? a.muted : null,
        wake_lock: !!engine.lock,
        sicherer_kontext: !!window.isSecureContext,
        gesten: engine.gestures,
        wiederherstellungen: engine.recoveries,
        laeuft_seit_min: engine.startedAt
          ? Math.round((Date.now() - engine.startedAt) / 60000) : 0,
        hinweis: engine.note,
        user_agent: navigator.userAgent,
        viewport: window.innerWidth + "x" + window.innerHeight,
        dpr: window.devicePixelRatio,
        sichtbar: !document.hidden,
        video_box: KA_SIZE + "px @ " + KA_OPACITY,
      };
    };
  }

  // -------------------------------------------------------------------- card
  class ModernEnergyKeepAwakeCard extends HTMLElement {
    setConfig(config) {
      this._config = Object.assign({ show_status: "problem", diagnose: false }, config || {});
      if (!this.shadowRoot) this.attachShadow({ mode: "open" });
      this._render();
      // Only Fire OS needs this. On a phone or desktop a permanent media
      // session drains the battery, occupies the lock-screen controls and can
      // interrupt music — and those platforms never had the problem anyway.
      if (IS_FIRE_OS || FORCE || this._config.force) engine.start();
      if (!this._bound) {
        this._bound = (state, reason) => this._paint(state, reason);
        engine.listeners.push(this._bound);
      }
      this._paint(engine.state, engine.reason);
      this._scheduleReport();
    }

    set hass(h) {
      this._hass = h;
      this._scheduleReport();
    }

    /**
     * Publish the engine state into a sensor so the situation on a device you
     * cannot open devtools on — an Echo Show — can be inspected from Home
     * Assistant. Only runs when diagnose is switched on.
     *
     * Each device gets its own entity, otherwise whichever browser reported
     * last would overwrite the others and the Echo Show's state would be
     * masked by a desktop that is working fine.
     */
    _deviceSlug() {
      const ua = navigator.userAgent || "";
      let kind = "browser";
      if (/\bAEO[A-Z]{2}/i.test(ua)) kind = "echo_show";
      else if (/\bAFT[A-Z0-9]/i.test(ua)) kind = "fire_tv";
      else if (/\bKF[A-Z]{2,}/i.test(ua)) kind = "fire_tablet";
      else if (/\bSilk\//i.test(ua)) kind = "silk";
      else if (/Android/i.test(ua)) kind = "android";
      else if (/iPhone|iPad/i.test(ua)) kind = "ios";
      else if (/Macintosh/i.test(ua)) kind = "mac";
      else if (/Windows/i.test(ua)) kind = "windows";

      // A stable per-browser id keeps two devices of the same kind apart.
      let id = "";
      try {
        id = localStorage.getItem("modernEnergyCardKeepAwakeId") || "";
        if (!id) {
          id = Math.random().toString(36).slice(2, 6);
          localStorage.setItem("modernEnergyCardKeepAwakeId", id);
        }
      } catch (e) { id = "x"; }
      return kind + "_" + id;
    }

    _scheduleReport() {
      if (!this._config || !this._config.diagnose || !this._hass) return;
      // Nothing worth reporting from a device the engine deliberately skips.
      if (!engine.started) return;
      if (this._repT) return;
      const slug = this._deviceSlug();
      const push = () => {
        try {
          const r = engine.report();
          this._hass.callApi("POST", "states/sensor.modern_energy_card_keep_awake_" + slug, {
            state: r.state,
            attributes: Object.assign({
              friendly_name: "Keep Awake " + slug,
              icon: "mdi:monitor-eye",
            }, r),
          });
        } catch (e) { /* not permitted or offline; ignore */ }
      };
      push();
      this._repT = setInterval(push, 30000);
    }

    disconnectedCallback() {
      const i = engine.listeners.indexOf(this._bound);
      if (i >= 0) engine.listeners.splice(i, 1);
      this._bound = null;
      if (this._repT) { clearInterval(this._repT); this._repT = null; }
    }

    connectedCallback() {
      if (this._config && !this._bound) {
        this._bound = (state, reason) => this._paint(state, reason);
        engine.listeners.push(this._bound);
        this._paint(engine.state, engine.reason);
      }
      this._scheduleReport();
    }

    _render() {
      this.shadowRoot.innerHTML = `
        <style>
          :host { display: block; }
          .box {
            display: none; align-items: center; gap: 8px;
            padding: 8px 12px; border-radius: 10px;
            font: 500 14px/1.3 var(--paper-font-body1_-_font-family, system-ui), sans-serif;
            color: #fff;
          }
          .box[data-show="1"] { display: flex; }
          .box[data-state="on"]   { background: rgba(0,160,85,.55); }
          .box[data-state="wait"] { background: rgba(205,145,0,.65); }
          .box[data-state="off"]  { background: rgba(200,45,45,.68); }
          .dot { width: 8px; height: 8px; border-radius: 50%; background: currentColor; flex: none; }
        </style>
        <div class="box" data-state="wait" data-show="0">
          <span class="dot"></span><span class="txt"></span>
        </div>`;
    }

    _paint(state, reason) {
      if (!this.shadowRoot) return;
      const box = this.shadowRoot.querySelector(".box");
      if (!box) return;
      const mode = this._config.show_status;   // always | problem | never
      const visible = mode === "always" || (mode !== "never" && state !== "on");
      box.dataset.state = state;
      box.dataset.show = visible ? "1" : "0";
      box.querySelector(".txt").textContent = reason;
      this.style.display = visible ? "block" : "none";
    }

    getCardSize() { return 0; }
    getGridOptions() {
      const visible = this._config && this._config.show_status === "always";
      return { columns: "full", rows: visible ? 1 : 0, min_rows: 0 };
    }

    static getStubConfig() { return { show_status: "problem" }; }
    static getConfigElement() {
      return document.createElement("modern-energy-keep-awake-card-editor");
    }
  }

  class ModernEnergyKeepAwakeCardEditor extends HTMLElement {
    setConfig(config) { this._config = config || {}; this._render(); }
    set hass(h) { this._hass = h; if (this._form) this._form.hass = h; }

    _render() {
      if (this._form) return;
      const form = document.createElement("ha-form");
      form.schema = [
        { name: "show_status", label: "Statusanzeige",
          selector: { select: { mode: "dropdown", options: [
            { value: "problem", label: "Nur bei Problemen (empfohlen)" },
            { value: "always", label: "Immer anzeigen" },
            { value: "never", label: "Nie anzeigen" },
          ] } } },
        { name: "diagnose", label: "Diagnose an sensor.modern_energy_card_keep_awake senden",
          selector: { boolean: {} } },
      ];
      form.computeLabel = (s) => s.label || s.name;
      form.data = this._config;
      if (this._hass) form.hass = this._hass;
      form.addEventListener("value-changed", (ev) => {
        this._config = ev.detail.value;
        this.dispatchEvent(new CustomEvent("config-changed", {
          detail: { config: this._config }, bubbles: true, composed: true,
        }));
      });
      this._form = form;
      this.appendChild(form);
    }
  }

  if (!customElements.get("modern-energy-keep-awake-card")) {
    customElements.define("modern-energy-keep-awake-card", ModernEnergyKeepAwakeCard);
    customElements.define("modern-energy-keep-awake-card-editor", ModernEnergyKeepAwakeCardEditor);
    window.customCards = window.customCards || [];
    window.customCards.push({
      type: "modern-energy-keep-awake-card",
      name: "Modern Energy Card – Bildschirm wachhalten",
      description: "Hält Echo Show und Fire-Tablets wach, ohne iframe und ohne Netzwerkzugriff.",
      preview: false,
    });
    console.info("%c MODERN-ENERGY-CARD KEEP-AWAKE %c " + VERSION + " ",
      "background:#0a7;color:#fff;border-radius:3px 0 0 3px",
      "background:#134;color:#fff;border-radius:0 3px 3px 0");
  }

  // -------------------------------------------------------------- auto start
  // Panel views render only their first card, so a keeper card cannot be
  // placed there at all. This resource is a module and loads on every
  // dashboard regardless of which cards are used, which lets Fire OS devices
  // start the engine on their own — including on panel views.
  //
  // Deliberately limited to Fire OS: an active media session on a phone or
  // desktop would occupy the lock-screen controls and could interrupt music.
  // AEOSY is the Echo Show 15 (2nd gen); AEO*/AFT*/KF* cover the other Echo
  // Show, Fire TV and Fire tablet models.
  if (IS_FIRE_OS) {
    var boot = function () { engine.start(); };
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", boot, { once: true });
    } else {
      boot();
    }
  }
})();
